// BAD: this key ships to every visitor's browser
const key = "sk-proj-abc123...";
fetch("https://api.openai.com/v1/chat", {
  headers: { Authorization: `Bearer ${key}` }
});

// browser -> your server -> OpenAI
// file: /api/chat.js  (runs on the server only)
const key = process.env.OPENAI_API_KEY; // stays server-side
// the browser just calls /api/chat, never OpenAI directly

// pseudo-code at the top of the route
if (!session) return res.status(401);   // must be logged in
if (await tooManyRequests(ip)) return res.status(429);
// cap the payload so nobody burns tokens with a giant one
if (body.message.length > 2000) return res.status(413);

// BAD: trusts whatever id the browser sent
db.orders.find({ id: params.id })

// GOOD: tied to the logged-in user
db.orders.find({ id: params.id, userId: session.userId })

// validate first
const schema = z.object({ message: z.string().max(2000) });
const { message } = schema.parse(body); // throws on junk

// parameterised query: the ? is filled safely
db.query("SELECT * FROM notes WHERE title = ?", [message]);

// return this to the user
res.status(500).json({
  error: "Something went wrong",
  ref: "err_8f2a"   // you look this up in the logs
});
// the stack trace goes to the log, not the response

const tools = [{
  name: "get_weather",
  description:
    "Current weather for a city. Use when asked about " +
    "conditions or temperature right now.",
  input_schema: {
    type: "object",
    properties: { city: { type: "string" } },
    required: ["city"],
    additionalProperties: false,
  },
  // arguments are guaranteed to match the schema
  strict: true,
}];

import Anthropic from "@anthropic-ai/sdk";
const client = new Anthropic();

const goal = "What should I wear in Copenhagen?";
let messages = [{ role: "user", content: goal }];

while (true) {
  const res = await client.messages.create({
    model: "claude-opus-5",
    max_tokens: 4096,
    tools,
    messages,
  });
  if (res.stop_reason === "end_turn") break;  // done

  messages.push({ role: "assistant", content: res.content });

  const calls = res.content
    .filter((b) => b.type === "tool_use");

  const results = await Promise.all(
    calls.map(async (c) => ({
      type: "tool_result",
      tool_use_id: c.id,
      content: await runTool(c.name, c.input),
    })),
  );

  // every result, in one message
  messages.push({ role: "user", content: results });
}

let steps = 0;
while (steps < 10) {      // the ceiling
  steps += 1;
  // ... the loop above ...
}

if (steps >= 10) {
  // Out of budget, not finished.
  // Say so instead of pretending.
  console.warn("hit the step budget, goal unconfirmed");
}
